#include <algorithm>
#include <iostream>
#include <vector>

struct Rect
{
    int left{}, top{}, right{}, bottom{};
};

class Invalid
{
public:
    void invalidate(Rect r) {}
    Rect bounds() const { return {}; }

private:
    std::vector<Rect> m_rects{};
};

int main()
{
    Invalid inv{};
    inv.invalidate({10, 10, 50, 50});
    inv.invalidate({40, 40, 100, 80});
    Rect b{inv.bounds()};
    std::cout << b.left << ' ' << b.right << '\n';
}
